// CSD_RATIONALE_BEGIN
// Root cause analysis from prior attempts:
// - Attempt 43 (best, 52%): GroupBoostedConstrainedStep(6.0) with immediate IsCompletePrefix closure.
//   Primary failure: 141/300 semantic mismatches. The model emits e.g. "SELECT city" which is
//   syntactically complete but missing FROM/WHERE/GROUP BY clauses. IsCompletePrefix fires
//   immediately and CloseConstrainedSpan closes the span too early.
// - Attempt 52 (0%): Used SpeculativeConstrainedRollout which is not in the allowed API set.
//   162/300 runtime errors from '_LogitsProxy' attribute not found.
//
// Primary fix: FROM-detection heuristic.
//   When IsCompletePrefix fires, render the current constrained output and check whether
//   "FROM" or "from" appears as a substring. Only close immediately if FROM is present
//   (i.e., the SQL has a table clause) OR the SQL is very long (>= 80 tokens, which
//   indicates a repetition loop — close and let Phase 4 handle cleanup).
//   If IsCompletePrefix fires but no FROM and short, fall through to generate the next
//   token. GroupBoostedConstrainedStep hard-masks to parser-valid next tokens, so the
//   model will naturally generate "FROM table_name" as a valid extension.
//
// Secondary fix: repetition-loop guard.
//   When |currentConstrainedOut| >= 80 and IsCompletePrefix, close immediately. This
//   cuts off runaway SELECT-list hallucinations before they hit the token budget.
//
// All other parameters unchanged from attempt 43 (best):
//   - 5-step free preamble for "SQL: " prefix
//   - Force-open "<<" if model doesn't emit it
//   - GroupBoostedConstrainedStep(6.0) for schema-token preference
//   - CloseSpanWithinBudget(≤80) safety net
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 preamble: insideConstrainedOut flips true only when RenderedEndsWith("<<")
//   fires. We set currentConstrainedOut := [] which satisfies IsValidPrefix([]) by
//   method precondition. EOS break leaves insideConstrainedOut false (vacuous).
//
//   Phase 2 OpenConstrainedSpan: runs only when !insideConstrainedOut. Helper sets
//   currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
//   Phase 3 main loop:
//     Close-immediately branch (hasFrom or long): CloseConstrainedSpan requires and
//     uses IsCompletePrefix (satisfied by the outer if-guard), then sets
//     insideConstrainedOut := false and currentConstrainedOut := [], making the
//     implication vacuously true.
//     Generate branch (no-close): GroupBoostedConstrainedStep hard-masks to
//     parser-valid tokens or EOS. If non-EOS, AppendConstrainedToken extends
//     currentConstrainedOut by one valid token, preserving IsValidPrefix by the parser
//     monotone-extension contract. If EOS and IsCompletePrefix, CloseConstrainedSpan
//     sets insideConstrainedOut := false (vacuous). If EOS and not complete, break
//     leaves state unchanged (still valid by prior invariant).
//
//   Phase 4: CloseSpanWithinBudget postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut); !insideOut ==> currentOut == [].
//
// Invariant 2: progress  |generated| <= |generatedPrefix| + steps
//
//   Phase 1: UnconstrainedStep increments steps by 1, appends at most 1 token (0 on EOS,
//   1 on non-EOS). Ratio ≤ 1:1 per iteration.
//
//   Phase 2: OpenConstrainedSpan increments steps by 1, appends exactly 1 "<<" token.
//   Ratio 1:1.
//
//   Phase 3:
//     Close-immediately branch: steps += 1, CloseConstrainedSpan appends at most 1 ">>"
//     token. Net: ≤ 1 token per +1 step. ✓
//     Generate branch: steps += 1 (GroupBoostedConstrainedStep). Non-EOS path:
//     AppendConstrainedToken appends 1 token; total +1 step, +1 token. ✓
//     EOS+close path: steps += 1 more, CloseConstrainedSpan appends ≤ 1 token;
//     total +2 steps, +≤1 token. ✓  EOS-only break: no additional growth. ✓
//
//   Phase 4: CloseSpanWithinBudget postcondition |generatedOut| <= |generated| + budget.
//   We set steps := steps + closeBudget where closeBudget <= remaining = maxSteps - steps,
//   so steps_new <= maxSteps and |generated_new| <= |generatedPrefix| + steps_new. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a complete SQL SELECT statement using ONLY exact table and column names from the provided schema. ALWAYS include FROM clause with exact table name. Include WHERE when filtering rows. Include GROUP BY and HAVING for per-group conditions. Use ORDER BY col DESC LIMIT 1 for maximum/minimum queries. No aliases, no markdown, no explanation.");

var steps: nat := 0;

// Phase 1: Short preamble to allow model to emit "SQL: " prefix (at most 5 steps)
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard parser control with FROM-detection-based closure.
// When IsCompletePrefix fires, only close if FROM clause is present OR SQL is
// very long (repetition loop guard). Otherwise continue generating.
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];

  if parser.IsCompletePrefix(currentConstrainedOut) {
    // Check whether generated SQL includes a FROM clause
    var curStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var fromCount := CSDHelpers.CountSubstring(curStr, "FROM") + CSDHelpers.CountSubstring(curStr, "from");
    if fromCount > 0 || |currentConstrainedOut| >= 80 {
      // SQL has FROM clause (semantically meaningful) OR is suspiciously long
      // (repetition loop) — close the span now
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
      break;
    }
    // Else: IsCompletePrefix but no FROM yet and short SQL — fall through to generate
    // the next token. The model should produce "FROM table_name" as a valid extension.
  }

  // Generate next constrained token (covers both incomplete SQL and complete-but-no-FROM)
  var next := helpers.GroupBoostedConstrainedStep(
    lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
  );
  steps := steps + 1;

  if next == eosToken {
    // EOS received — close if current state is complete, otherwise abandon span to Phase 4
    if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    }
    break;
  } else {
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Phase 4: Safety net — if span still open and budget remains, attempt to close within budget
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

